referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const clone = (v) => JSON.parse(JSON.stringify(v));
  const base = clone(d.base),
    next = clone(d.base);
  for (const e of d.recipe) {
    let n = next;
    for (const k of e.path.slice(0, -1)) n = n[k];
    n[e.path.at(-1)] = clone(e.value);
  }
  return { base, next };
}

